mapper.select:
SELECT * FROM ( SELECT rownum rn, TB.* FROM (
SELECT f.IFAVOR_NO, f.SGUBUN, f.ILAW_ID, f.SITEM, f.SDESC, f.SUSER_ID, f.SUSER_NAME, SUBSTR(f.SINS_DT, 1, 16) AS SINS_DT, f.SSYS_ID, cur.IPROM_NO AS PROM_NO, cur.STITLE AS PROM_TITLE, CASE WHEN cur.SSTART_DT > TO_CHAR(SYSDATE, 'YYYY-MM-DD') THEN 'Y' ELSE 'N' END AS PENDING_YN, CASE WHEN f.SGUBUN = 'PROVISION' AND NOT EXISTS ( SELECT 1 FROM TB_PROV_VRSN PV, TB_PROM PR WHERE PV.IPROM_NO = PR.IPROM_NO AND PR.ILAW_ID = f.ILAW_ID AND PV.SFULL_ITEM = f.SITEM AND PR.ILAW_NO = ( SELECT MAX(PR2.ILAW_NO) FROM TB_PROV_VRSN PV2, TB_PROM PR2 WHERE PV2.IPROM_NO = PR2.IPROM_NO AND PR2.ILAW_ID = f.ILAW_ID AND PV2.SFULL_ITEM = f.SITEM ) AND NVL(PV.SDISP_YN, 'Y') = 'Y' ) AND NOT EXISTS ( SELECT 1 FROM TB_PROV_HTML PH, TB_PROM PR WHERE PH.IPROM_NO = PR.IPROM_NO AND PR.ILAW_ID = f.ILAW_ID AND PH.SITEM = f.SITEM AND PR.ILAW_NO = ( SELECT MAX(PR3.ILAW_NO) FROM TB_PROV_HTML PH3, TB_PROM PR3 WHERE PH3.IPROM_NO = PR3.IPROM_NO AND PR3.ILAW_ID = f.ILAW_ID AND PH3.SITEM = f.SITEM ) AND NVL(PH.SDISP_YN, 'Y') = 'Y' ) THEN 'Y' ELSE 'N' END AS PROV_DELETED FROM TB_FAVOR f LEFT JOIN TB_PROM cur ON cur.ILAW_ID = f.ILAW_ID AND cur.SEXISTING_YN = 'Y' WHERE f.SUSER_ID = #{userId}
AND f.SGUBUN = #{vo.searchGubun}
AND (UPPER(f.SDESC) LIKE '%' || UPPER(#{vo.searchKeyword}) || '%' OR UPPER(f.SITEM) LIKE '%' || UPPER(#{vo.searchKeyword}) || '%')
ORDER BY f.IFAVOR_NO DESC ) TB ) WHERE rn BETWEEN #{vo.firstIndex}+1 AND #{vo.firstIndex}+#{vo.recordCountPerPage}

SELECT COUNT(*)
  FROM TB_FAVOR f
 WHERE f.SUSER_ID = #{userId}

   AND f.SGUBUN = #{vo.searchGubun}


   AND (UPPER(f.SDESC) LIKE '%' || UPPER(#{vo.searchKeyword}) || '%'
    OR  UPPER(f.SITEM) LIKE '%' || UPPER(#{vo.searchKeyword}) || '%')

SELECT IFAVOR_NO, SGUBUN, ILAW_ID, SITEM, SDESC, SUSER_ID, SUSER_NAME, SINS_DT, SSYS_ID
  FROM TB_FAVOR
 WHERE SUSER_ID = #{userId}
   AND ILAW_ID  = #{lawId}
   AND SITEM    = #{item}

SELECT IFAVOR_NO, SGUBUN, ILAW_ID, SITEM, SDESC, SUSER_ID, SUSER_NAME, SINS_DT, SSYS_ID
  FROM TB_FAVOR
 WHERE SUSER_ID = #{userId}
   AND ILAW_ID  = #{lawId}
 ORDER BY SITEM

mapper.update:
UPDATE TB_FAVOR
   SET ISEEN_LAW_NO = GREATEST(NVL(ISEEN_LAW_NO, 0), #{lawNo})
 WHERE SUSER_ID = #{userId}
   AND ILAW_ID  = #{lawId}

UPDATE TB_FAVOR SET
	SGUBUN  = #{gubun},
	SITEM   = #{item},
	SDESC   = #{description}
WHERE IFAVOR_NO = #{favorNo}

UPDATE TB_FAVOR
   SET SITEM = #{newItem}
 WHERE ILAW_ID = ( SELECT ILAW_ID FROM TB_PROM WHERE IPROM_NO = #{regPromNo} )
   AND SITEM   = #{oldItem}
